css:
:scope{display:block;width:100%}.pw{--bg:#01111D;--tx:#EDE6D8;--lb:#BBAFA3;--rl:#C6A15B;--hl:#7B868066;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#E0D9CB;--tx:#01111D;--lb:#5E3A3C;--rl:#8C5B46;--hl:#BBAFA3}.pw[data-ground="sand"]{--bg:#BBAFA3;--tx:#01111D;--lb:#5E3A3C;--rl:#01111D;--hl:#01111D40}.pw[data-ground="olive"]{--bg:#182727}.pw[data-ground="oxblood"]{--bg:#321013;--hl:#95665A}.pw[data-ground="umber"]{--bg:#5E3A3C;--rl:#BBAFA3;--hl:#BBAFA366}.pw[data-ground="clay"]{--bg:#8C5B46;--lb:#EDE6D8;--rl:#EDE6D8;--hl:#EDE6D899}.pw[data-ground="sage"]{--bg:#7B8680;--tx:#01111D;--lb:#01111D;--rl:#01111D;--hl:#01111D40}
.pw__in{box-sizing:content-box;max-width:1000px;margin:0 auto;padding:128px 32px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:1px;background:var(--rl);margin:28px 0 32px}
.pw__in>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.08;color:var(--tx);text-wrap:balance}
.pw__intro{margin:24px 0 0;font-size:21px;line-height:1.5}
.pw__ol{margin:48px 0 0;padding:0;list-style:none;display:flex;flex-direction:column;counter-reset:m}
.pw__ol li{counter-increment:m;display:flex;gap:28px;align-items:baseline;border-top:1px solid var(--hl);padding:22px 0}
.pw__ol li:last-child{border-bottom:1px solid var(--hl)}
.pw__n::before{content:counter(m,decimal-leading-zero);font-family:var(--os-font-label);font-size:12px;letter-spacing:.2em;color:var(--lb)}
.pw__t{font-family:var(--os-font-heading);font-weight:500;font-size:32px;line-height:1.2}
.pw__close{margin:40px 0 0;font-family:var(--os-font-heading);font-style:italic;font-weight:500;font-size:30px;line-height:normal}
@media (max-width:767px){.pw__in{padding:64px 20px}.pw__kicker{font-size:12px;letter-spacing:.24em}.pw__rule{width:48px;margin:24px 0}.pw__h2{font-size:40px;line-height:1.1}.pw__intro{font-size:19px;margin-top:20px}.pw__ol{margin-top:32px}.pw__ol li{gap:18px;padding:18px 0}.pw__t{font-size:25px}.pw__close{font-size:27px;margin-top:32px}}
